<script setup>
import {computed,ref} from 'vue'
import {useArcade} from '../stores/arcade'
import DressedPartner from './DressedPartner.vue'
const props=defineProps({items:{type:Array,required:true}})
const s=useArcade(),selectedId=ref(props.items[0]?.id),busy=ref(false),notice=ref(''),error=ref('')
const pet=computed(()=>s.data.pet),selected=computed(()=>props.items.find(i=>i.id===selectedId.value)),owned=computed(()=>!!selected.value&&pet.value.owned.includes(selected.value.id)),equipped=computed(()=>selected.value?.id===pet.value.wear)
const page=ref(0),pageCount=computed(()=>Math.max(1,Math.ceil(props.items.length/9)))
const slots=computed(()=>Array.from({length:9},(_,index)=>props.items[page.value*9+index]??null))
function changePage(delta){if(busy.value)return;page.value=Math.max(0,Math.min(pageCount.value-1,page.value+delta));selectedId.value=props.items[page.value*9]?.id;notice.value='';error.value=''}
function select(item){if(!busy.value){selectedId.value=item.id;notice.value='';error.value=''}}
async function wear(){if(!selected.value||busy.value||equipped.value)return;busy.value=true;notice.value='';error.value='';const item=selected.value,alreadyOwned=owned.value;try{await s.petAction('wear',item.id);notice.value=alreadyOwned?item.name+'을 착용했어요!':item.name+' 구매와 착용이 완료됐어요!'}catch(e){error.value=e.message}finally{busy.value=false}}
async function remove(){if(busy.value||!pet.value.wear)return;busy.value=true;notice.value='';error.value='';try{await s.petAction('remove');notice.value='꾸미기를 벗겼어요. 아이템은 슬롯에 보관됩니다.'}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><aside class="item-device" aria-label="포켓몬 아이템 슬롯"><div class="device-top"><div class="device-lens" aria-hidden="true"></div><span class="device-indicators" aria-hidden="true"><i></i><i></i><i></i></span><span class="device-brand">SPOKEMON / ITEM CASE</span></div><div class="device-book"><section class="device-left"><div class="device-screen-frame"><div class="screen-dots" aria-hidden="true">● ●</div><div class="device-partner-screen"><DressedPartner size="device"/></div><div class="device-screen-foot" aria-hidden="true"><i></i><span>≡</span></div></div><div class="device-identity"><span>MY PARTNER</span><h3>{{s.partner.name}}</h3><b>Lv.{{s.level}}</b></div><div class="device-bottom-controls" aria-hidden="true"><div class="device-green-key"></div><div class="device-dpad"><span>✚</span></div></div><p class="device-lock-note">{{s.data.partnerLocked?'CHANGE · 5,000 P':'CHOOSE YOUR PARTNER'}}</p></section><div class="device-hinge" aria-hidden="true"><i></i><i></i></div><section class="device-right"><div class="device-lcd"><p>나의 아이템 슬롯</p><span>보유 {{pet.owned.length}}개 / 착용 {{pet.wear?'1':'0'}}개</span><b>🪙 {{s.data.coins.toLocaleString()}}</b></div><div class="device-slot-grid" aria-label="아이템 보관함"><button v-for="(item,index) in slots" :key="index" type="button" :class="['device-slot',{selected:item?.id===selectedId,owned:item&&pet.owned.includes(item.id),equipped:item&&pet.wear===item.id,empty:!item}]" :disabled="!item||busy" :aria-label="item?item.name+' 슬롯':'빈 아이템 슬롯 '+(index+1)" :aria-pressed="!!item&&item.id===selectedId" @click="select(item)"><template v-if="item"><span class="device-item-icon">{{item.id}}</span><small>{{pet.wear===item.id?'착용':pet.owned.includes(item.id)?'보유':'SHOP'}}</small></template><span v-else class="device-slot-empty" aria-hidden="true">＋</span></button></div><div class="device-item-pages"><button :disabled="page===0||busy" aria-label="이전 아이템 페이지" @click="changePage(-1)">◀</button><span>{{page+1}} / {{pageCount}}</span><button :disabled="page===pageCount-1||busy" aria-label="다음 아이템 페이지" @click="changePage(1)">▶</button></div><div v-if="selected" class="device-item-detail"><h3>{{selected.name}}</h3><p>{{equipped?'현재 착용 중이에요.':owned?'내 아이템 · 무료로 다시 착용해요.':selected.price+'코인으로 구매할 수 있어요.'}}</p><button class="device-action" :disabled="busy||equipped||(!owned&&s.data.coins<selected.price)" @click="wear">{{busy?'처리 중…':equipped?'✓ 착용 중':owned?'착용하기':'구매 · '+selected.price+' 🪙'}}</button><p v-if="!owned&&s.data.coins<selected.price" class="device-no-coins">퀴즈 정답으로 코인을 모아 보세요!</p></div><button class="device-remove" :disabled="!pet.wear||busy" @click="remove">꾸미기 벗기기</button></section></div><div class="device-footer"><span>SELECT A SLOT · MAKE IT YOURS</span><i aria-hidden="true"></i></div><p v-if="notice" class="device-feedback" role="status">{{notice}}</p><p v-if="error" class="device-feedback device-error" role="alert">{{error}}</p></aside></template>
